import 'dart:convert';
import 'dart:io';

// Run after editing assets/config/running_rules.json. A generated local snapshot
// keeps synchronous generators deterministic, including offline startup/tests.
void main() {
  final source = File('assets/config/running_rules.json').readAsStringSync();
  final canonical = jsonEncode(jsonDecode(source));
  File('lib/services/generated/running_rules.g.dart').writeAsStringSync(
    '// GENERATED by tool/generate_running_rules.dart. Do not edit.\n'
    'const runningRulesJson = r\'\'\'$canonical\'\'\';\n',
  );
}
